// ─── Core Shape interface ─────────────────────────────────────────────────────

/**
 * Stable plugin-facing shape interface.
 *
 * This is the canonical type for all shapes returned by the Logos plugin API.
 * All fields are camelCase regardless of the internal kebab-case representation
 * in the Clojure / Rust layers.
 */
export interface Shape {
  /** UUID v4 string */
  readonly id: string;
  type: ShapeType;
  name: string;
  x: number;
  y: number;
  width: number;
  height: number;
  /** Rotation in degrees (0–360) */
  rotation: number;
  /** Opacity 0 (transparent) – 1 (opaque) */
  opacity: number;
  hidden: boolean;
  locked: boolean;
  blendMode: BlendMode;
  fills: Fill[];
  strokes: Stroke[];
  shadows: Shadow[];
  blur?: Blur;
  constraintsH: HorizontalConstraint;
  constraintsV: VerticalConstraint;
  transform: Transform;
  /** Child shape IDs (frames and groups only) */
  children: string[];
  /** UUID of containing frame, or null for root shapes */
  frameId: string | null;
  /** UUID of parent shape, or null for root shapes */
  parentId: string | null;
  /**
   * Corner radii `[topLeft, topRight, bottomRight, bottomLeft]` (rects only).
   * Each value in logical pixels.
   */
  corners?: [number, number, number, number];
  /** Bool operation type (bool shapes only) */
  boolType?: BoolType;
}

/**
 * Mutable subset of Shape used for plugin update calls.
 * `id`, `type`, `children`, `frameId`, `parentId` are immutable.
 */
export type ShapePatch = Partial<
  Pick<Shape,
    | 'name'
    | 'x' | 'y' | 'width' | 'height'
    | 'rotation' | 'opacity' | 'hidden' | 'locked'
    | 'blendMode' | 'fills' | 'strokes' | 'shadows' | 'blur'
    | 'constraintsH' | 'constraintsV'
    | 'transform' | 'corners'
  >
>;

